#!/bin/bash
echo "GameVox Self-Hosted: Bitte gamevox-self-hosted-server aus der GameVox-App in dieses Serververzeichnis hochladen."
if [ ! -f /mnt/server/gamevox-self-hosted-server ]; then echo "Binary fehlt noch; Installation wird trotzdem abgeschlossen."; else chmod +x /mnt/server/gamevox-self-hosted-server; fi
